import {diagnose,relatedCases,customerDraft,proofIsCurrent} from './operations.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const labels={attention:'Access overdue',waiting:'Within delivery window',review:'Needs review',resolved:'Verified',access_present:'Verify existing access',payment_pending:'Payment pending',unpaid:'No payment',unknown_age:'Payment time unavailable'};
export function operationsPanel(s,cases,{graceMinutes=5,related=false,busy=false,backend=false}={}){
 const peers=relatedCases(s,cases),rows=related?[s,...peers]:cases;
 const overdue=cases.filter(x=>x.monitor?.status==='attention').length;
 return `<section class="ops-console" aria-label="Access monitoring"><div class="ops-heading"><div><span class="eyebrow">ACCESS WATCH / ${backend?'SERVER RECONCILIATION':'SIMULATED PORTFOLIO'}</span><h3>Catch the gap. Follow the pattern.</h3><p>${backend?'Checks saved purchases every 30 seconds while the server runs.':'Checks these sample purchases every 30 seconds while this page is open.'} Monitoring never approves or applies a repair.</p></div><div class="ops-metric"><strong>${overdue}</strong><span>access overdue</span></div></div><div class="ops-controls"><label>Expected access within <select aria-label="Delivery window" ${busy?'disabled':''}>${[1,5,10,15,30,60].map(n=>`<option value="${n}" ${graceMinutes===n?'selected':''}>${n} minute${n===1?'':'s'}</option>`).join('')}</select></label><button data-ops="scan" ${busy?'disabled':''}>Check purchases now</button><button data-ops="related" ${busy?'disabled':''}>Who else is affected? (${peers.length})</button>${related?'<button data-ops="all">Show all cases</button>':''}</div>${related?'<p class="ops-related-note">Similar enrollment error, same course, within 15 minutes. A shared cause is not confirmed. Each case needs its own review and approval.</p>':''}<div class="ops-cases" role="group" aria-label="Purchase cases">${rows.map(x=>{const d=diagnose(x),m=x.monitor;return `<button class="ops-case ${x.id===s.id?'selected':''}" data-case="${esc(x.id)}" ${busy?'disabled':''} aria-label="Open ${esc(x.customerName||'Maya')} case ${esc(x.id)}"><span class="ops-initial">${esc((x.customerName||'M')[0])}</span><span class="ops-case-person"><b>${esc(x.customerName||'Maya')}</b><small>${esc(d.title)}</small></span><span class="ops-case-status ${m?.status==='attention'?'overdue':''}">${esc(labels[m?.status]||'Not checked')}<small>${m?.elapsedMinutes==null?'No completed-payment age':Math.floor(m.elapsedMinutes)+' min since payment record'}</small></span><span aria-hidden="true">↗</span></button>`;}).join('')}</div><p class="ops-caption">${backend?'Isolated demonstration workspace; sample portfolio and any sandbox purchase are labeled.':'Fictional purchases; the timestamps are demo fixtures.'} ${s.monitor?.checkedAt?'Last checked '+new Date(s.monitor.checkedAt).toLocaleTimeString()+'.':''} ${s.monitor?.detectedAt?'Selected case flagged '+new Date(s.monitor.detectedAt).toLocaleTimeString()+'.':''}</p></section>`;
}
export function diagnosisPanel(s){const d=diagnose(s);return `<section class="ops-diagnosis" aria-label="Case diagnosis"><span class="ops-diagnosis-icon">${d.repair?'↗':'i'}</span><div><div class="eyebrow">DIAGNOSIS / RULES CHECKED</div><h4>${esc(d.title)}</h4><p>${esc(d.detail)}</p><strong>${esc(d.next)}</strong></div><span class="ops-route">${d.repair?'Review a repair':'No automatic grant'}</span></section>`;}
export function responsePanel(s,{mode='browser-simulation',draft=customerDraft(s,{mode})}={}){return `<section class="ops-response" aria-label="Customer response draft"><div><span class="eyebrow">FINISH THE CONVERSATION / DRAFT ONLY</span><h4>${proofIsCurrent(s)?'A checked outcome, ready to explain.':'Keep the customer informed.'}</h4><p>Evidence-based template, editable by the merchant. Nothing is sent. ${mode==='browser-simulation'?'Sample wording for this simulation.':''}</p></div><label for="customer-response">Review before copying</label><textarea id="customer-response" rows="6">${esc(draft.text)}</textarea><div class="ops-response-actions"><button class="button outline small" data-action="copy-draft">Copy customer response</button><button class="quiet" data-action="regenerate-draft">Reset from current evidence</button></div><p class="fine">${proofIsCurrent(s)?'Current verification passed.':'Access restoration has not been verified; this draft does not claim success.'} Draft resets when case evidence changes.</p></section>`;}
